  flame:'<path d="M12.5 3c.8 3.2 5 5.2 5 10.2a5.5 5.5 0 0 1-11 0c0-2.4 1.2-4 2.4-5.1.2 2.1 1.1 3.1 2.2 3.3-.5-3.1.2-5.9 1.4-8.4z"/>',
  target:'<circle cx="12" cy="12" r="8.5"/><circle cx="12" cy="12" r="4.5"/><circle cx="12" cy="12" r="1"/>',
