  bag:'<path d="M5 8h14l-1.2 11.2A2 2 0 0 1 15.8 21H8.2a2 2 0 0 1-2-1.8z"/><path d="M9 8V6.5a3 3 0 0 1 6 0V8"/>',
  hanger:'<path d="M12 7.5a2 2 0 1 1 2-2"/><path d="M12 7.5V9L3 16a1.5 1.5 0 0 0 .9 2.7h16.2A1.5 1.5 0 0 0 21 16l-9-7"/>',
  sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2.5v2M12 19.5v2M4.6 4.6 6 6M18 18l1.4 1.4M2.5 12h2M19.5 12h2M4.6 19.4 6 18M18 6l1.4-1.4"/>',
